#!/usr/bin/env python3
"""Aggregate numbers quoted in the manuscript -> ../manuscript/NUMBERS.md and LaTeX table bodies (tables.tex).
Sources: out2/summary2.json, out2/gate_water.json, out2/sidechain.json, out2/qc_*.json, out/summary.json (unconstrained search), out/*.zero.txt"""
import json, os, re, glob
import numpy as np
H = os.path.dirname(os.path.abspath(__file__)); M = os.path.join(H, "..", "manuscript")
R = json.load(open(H + "/out2/summary2.json")); SC = json.load(open(H + "/out2/sidechain.json"))
QC = {l: json.load(open(f"{H}/out2/qc_{l}.json")) for l in R}
import sys
sys.path.insert(0, H)
from trajectories import NAME, LENGTH, SEED, ORDER
assert list(R) == ORDER, "summary2.json is stale: run summarize2.py"
ms = lambda v: (float(np.mean(v)), float(np.std(v, ddof=1)), float(np.min(v)), float(np.max(v)))
L = ["# Numbers quoted in the manuscript (generated by analysis/make_tables.py — do not edit by hand)\n"]
nfr = sum(r["n_frames"] for r in R.values()); tsim = sum(LENGTH[l] for l in R); tprod = sum(r["t_ns"][1] - r["t_ns"][0] for r in R.values())
L.append(f"- trajectories {len(R)}; simulated {tsim} ns; analysed (t >= 20 ns) {tprod:.0f} ns; frames {nfr}")
def agg(name, vals, fmt="{:.3f}"):
    a = ms(vals); L.append(f"- {name}: mean of trajectory means " + fmt.format(a[0]) + " ± " + fmt.format(a[1]) + " (SD between trajectories), range " + fmt.format(a[2]) + "–" + fmt.format(a[3]))
agg("on-axis R_min (nm), gate region", [r["rc3"]["rmin_mean"] for r in R.values()])
L.append(f"- largest single-frame R_min: {max(r['rc3']['max'] for r in R.values()):.3f} nm; fraction of frames below 0.14 nm: {min(r['rc3']['frac_below_water'] for r in R.values()):.3f} (minimum over trajectories)")
L.append("- within-trajectory SD of R_min: " + ", ".join(f"{r['rc3']['rmin_sd']:.3f}" for r in R.values()))
for k in ("L318", "S314", "G310", "A306", "V302"):
    agg(f"R at {k} plane (nm)", [r["R_at_" + k][0] for r in R.values()])
for k, nm in ((318, "L318"), (314, "S314"), (310, "G310"), (306, "A306")):
    agg(f"Calpha diagonal {nm} (nm)", [r["diag_mean"][str(k)] / 10 for r in R.values()])
agg("S314 OG-OG shortest diagonal (nm)", [SC[l]["og_diag"][0] / 10 for l in R]); agg("L318 CD-CD shortest diagonal (nm)", [SC[l]["cd_diag"][0] / 10 for l in R])
for g, nm in (("ser_oh", "Ser314 hydroxyl (OG, HG1)"), ("ser_other", "Ser314 other atoms"), ("leu", "Leu318"), ("other", "other residues")):
    agg(f"limiting atom group: {nm} (%)", [100 * r["groups"][g] for r in R.values()], "{:.1f}")
agg("Ser314 as limiting residue (%)", [100 * r["residues"].get("SER314", 0) for r in R.values()], "{:.1f}")
agg("rc sensitivity: R_min(rc=0.15) (nm)", [r["rc1.5"]["rmin_mean"] for r in R.values()]); agg("rc sensitivity: R_min(rc=0.45) (nm)", [r["rc4.5"]["rmin_mean"] for r in R.values()])
agg("UNCONSTRAINED search (0.9 nm disk) R_min (nm)", [r["rc9"]["rmin_mean"] for r in R.values()]); agg("UNCONSTRAINED: off-axis offset of the sphere centre (nm)", [r["rc9"]["off_mean"] for r in R.values()], "{:.2f}")
agg("UNCONSTRAINED: fraction of frames below 0.14 nm", [r["rc9"]["frac_below_water"] for r in R.values()])
for res_ in ("SER314", "LEU318", "HSD228", "ALA317", "ILE311"):
    agg(f"UNCONSTRAINED: {res_} as limiting residue (%)", [100 * r["rc9"]["residues"].get(res_, 0) for r in R.values()], "{:.1f}")
agg("UNCONSTRAINED: residues other than Ser314/Leu318 (%)", [100 * (1 - r["rc9"]["residues"].get("SER314", 0) - r["rc9"]["residues"].get("LEU318", 0)) for r in R.values()], "{:.1f}")
agg("ALTERNATIVE radii (O 1.40, N 1.65): on-axis R_min (nm)", [r["camp_rc3"]["rmin_mean"] for r in R.values()]); agg("ALTERNATIVE radii: unconstrained R_min (nm)", [r["camp_rc9"]["rmin_mean"] for r in R.values()])
agg("filter: on-axis minimum radius (nm)", [r["R_sf_min"][0] for r in R.values()])
agg("water-free stretch at the gate (nm)", [r["gap_mean"] / 10 for r in R.values()], "{:.2f}")
agg("P(water-free stretch >= 0.3 nm)", [r["frac_gap_ge3"] for r in R.values()]); agg("waters within |z|<0.2, r<0.3 nm of the S314 plane", [r["w_core_r3"][0] for r in R.values()])
agg("waters in gate cylinder (|z|<0.5, r<0.6 nm)", [r["nw_cyl"][0] for r in R.values()], "{:.2f}"); agg("waters in cavity (0.6<z<2.0, r<0.6 nm)", [r["w_cav_r6"][0] for r in R.values()], "{:.1f}")
agg("K+ in filter region", [r["k_sf"][0] for r in R.values()], "{:.2f}"); agg("K+ in cavity", [r["k_cav"][0] for r in R.values()], "{:.2f}")
agg("Calpha RMSD whole construct (nm)", [QC[l]["rmsd_all_mean"] / 10 for l in R]); agg("Calpha RMSD pore domain (nm)", [QC[l]["rmsd_pd_mean"] / 10 for l in R])
lig = [x for l in R if "lig_disp_mean" in QC[l] for x in QC[l]["lig_disp_mean"]]; con = [x for l in R if "lig_w236_contact_frac" in QC[l] for x in QC[l]["lig_w236_contact_frac"]]
L.append(f"- retigabine: {len(lig)} ligand copies; mean centre displacement {np.mean(lig) / 10:.3f} nm (max of means {np.max(lig) / 10:.3f}); Trp236 contact fraction min {np.min(con):.3f}")
agg("gate-filter centre separation (nm)", [r["sf_z"][0] / 10 for r in R.values()], "{:.2f}"); agg("axis tilt (deg)", [r["tilt_deg"] for r in R.values()], "{:.1f}")
z = [open(f"{H}/out/{l}.zero.txt").read() for l in R]
bulk = [float(re.search(r":\s*([\d.]+) \+- ", x).group(1)) for x in z]
L.append(f"- zero test ({len(z)} trajectories): water density in the counting cylinder placed in bulk solvent {min(bulk):.1f}–{max(bulk):.1f} nm^-3 (TIP3P 33.4)")
open(M + "/NUMBERS.md", "w").write("\n".join(L) + "\n")


def stats(vals):
    v = np.asarray(vals, float); return float(v.mean()), float(v.std(ddof=1)), float(v.min()), float(v.max())
V = lambda f: [f(r) for r in R.values()]
S0 = [r for r in R.values() if r["system"] == "S0"]; S2 = [r for r in R.values() if r["system"] == "S2"]; S3 = [r for r in R.values() if r["system"] == "S3"]
RTG = S2 + S3; PIPS = S0 + S2
mac = {}
def put(name, val, fmt): mac[name] = fmt.format(val)
put("NTraj", len(R), "{:d}"); put("TSim", tsim / 1000, "{:.1f}"); put("TProd", tprod, "{:.0f}"); mac["NFrames"] = f"{nfr:,}".replace(",", r"\,")
m_, s_, lo, hi = stats(V(lambda r: r["rc3"]["rmin_mean"])); put("Rmin", m_, "{:.3f}"); put("RminSD", s_, "{:.3f}"); put("RminLo", lo, "{:.3f}"); put("RminHi", hi, "{:.3f}")
put("RminMax", max(r["rc3"]["max"] for r in R.values()), "{:.3f}")
assert min(r["rc3"]["frac_below_water"] for r in R.values()) == 1.0, "a frame reaches the water radius: rewrite the text"
for key, nm in (("L318", "RLeu"), ("S314", "RSer"), ("G310", "RGly")):
    m_, s_, lo, hi = stats(V(lambda r: r["R_at_" + key][0])); put(nm, m_, "{:.3f}"); put(nm + "SD", s_, "{:.3f}")
for key, nm in (("318", "DLeu"), ("314", "DSer"), ("310", "DGly")):
    m_, s_, lo, hi = stats(V(lambda r: r["diag_mean"][key] / 10)); put(nm, m_, "{:.3f}"); put(nm + "SD", s_, "{:.3f}")
m_, s_, _, _ = stats([SC[l]["og_diag"][0] / 10 for l in R]); put("DOG", m_, "{:.3f}"); put("DOGSD", s_, "{:.3f}")
m_, s_, _, _ = stats([SC[l]["cd_diag"][0] / 10 for l in R]); put("DCD", m_, "{:.3f}"); put("DCDSD", s_, "{:.3f}")
put("RminWithinLo", min(V(lambda r: r["rc3"]["rmin_sd"])), "{:.3f}"); put("RminWithinHi", max(V(lambda r: r["rc3"]["rmin_sd"])), "{:.3f}")
put("RminAlt", stats(V(lambda r: r["camp_rc3"]["rmin_mean"]))[0], "{:.3f}")
put("PLeuAlt", stats(V(lambda r: 100 * r["camp_rc3"]["residues"].get("LEU318", 0)))[0], "{:.0f}")
put("PSerAlt", stats(V(lambda r: 100 * r["camp_rc3"]["residues"].get("SER314", 0)))[0], "{:.0f}")
assert min(r["camp_rc3"]["frac_below_water"] for r in R.values()) == 1.0
put("PAlaFree", stats(V(lambda r: 100 * r["rc9"]["residues"].get("ALA317", 0)))[0], "{:.0f}")
put("PIleFree", stats(V(lambda r: 100 * r["rc9"]["residues"].get("ILE311", 0)))[0], "{:.0f}")
put("PSerOHLo", min(V(lambda r: 100 * r["groups"]["ser_oh"])), "{:.0f}"); put("PSerOHHi", max(V(lambda r: 100 * r["groups"]["ser_oh"])), "{:.0f}")
m_, s_, lo, hi = stats(V(lambda r: 100 * r["residues"].get("SER314", 0))); put("PSer", m_, "{:.0f}"); put("PSerLo", lo, "{:.0f}"); put("PSerHi", hi, "{:.0f}")
m_, s_, lo, hi = stats(V(lambda r: 100 * r["residues"].get("LEU318", 0))); put("PLeu", m_, "{:.0f}"); put("PLeuLo", lo, "{:.0f}"); put("PLeuHi", hi, "{:.0f}")
put("PSerOH", stats(V(lambda r: 100 * r["groups"]["ser_oh"]))[0], "{:.0f}")
assert max(r["groups"]["other"] for r in R.values()) == 0.0, "another residue limits the on-axis sphere: rewrite Sec. III C and the caption of Table III"
put("RminRcSmall", stats(V(lambda r: r["rc1.5"]["rmin_mean"]))[0], "{:.3f}"); put("RminRcLarge", stats(V(lambda r: r["rc4.5"]["rmin_mean"]))[0], "{:.3f}")
free = stats(V(lambda r: r["rc9"]["rmin_mean"]))[0]; put("RminFree", free, "{:.3f}"); put("FreeExcess", 100 * (free / float(mac["Rmin"]) - 1), "{:.0f}")
put("OffFree", stats(V(lambda r: r["rc9"]["off_mean"]))[0], "{:.2f}")
m_, s_, lo, hi = stats(V(lambda r: 100 * (1 - r["rc9"]["residues"].get("SER314", 0) - r["rc9"]["residues"].get("LEU318", 0))))
put("POffRes", m_, "{:.0f}"); put("POffResLo", lo, "{:.0f}"); put("POffResHi", hi, "{:.0f}")
put("PHisFree", stats(V(lambda r: 100 * r["rc9"]["residues"].get("HSD228", 0)))[0], "{:.0f}")
assert min(r["rc9"]["frac_below_water"] for r in R.values()) == 1.0, "unconfined search exceeds the water radius in some frame: rewrite Sec. III D"
put("Tilt", stats(V(lambda r: r["tilt_deg"]))[0], "{:.1f}")
put("BulkLo", min(bulk), "{:.1f}"); put("BulkHi", max(bulk), "{:.1f}")
m_, s_, _, _ = stats([QC[l]["rmsd_all_mean"] / 10 for l in R]); put("RmsdAll", m_, "{:.2f}"); put("RmsdAllSD", s_, "{:.2f}")
m_, s_, _, _ = stats([QC[l]["rmsd_pd_mean"] / 10 for l in R]); put("RmsdPD", m_, "{:.2f}"); put("RmsdPDSD", s_, "{:.2f}")
assert min(con) == 1.0, "a retigabine left Trp236: rewrite the text"
put("NLig", len(lig), "{:d}"); put("LigDisp", np.ceil(np.max(lig) * 10) / 100, "{:.2f}")
put("WCoreLo", min(V(lambda r: r["w_core_r3"][0])), "{:.2f}"); put("WCoreHi", max(V(lambda r: r["w_core_r3"][0])), "{:.2f}")
put("PGapLo", 100 * min(V(lambda r: r["frac_gap_ge3"])), "{:.0f}"); put("PGapHi", 100 * max(V(lambda r: r["frac_gap_ge3"])), "{:.0f}")
put("GapLo", min(V(lambda r: r["gap_mean"] / 10)), "{:.1f}"); put("GapHi", max(V(lambda r: r["gap_mean"] / 10)), "{:.1f}")
put("NcavLo", min(V(lambda r: r["w_cav_r6"][0])), "{:.1f}"); put("NcavHi", max(V(lambda r: r["w_cav_r6"][0])), "{:.1f}")
put("NgLo", min(V(lambda r: r["nw_cyl"][0])), "{:.1f}"); put("NgHi", max(V(lambda r: r["nw_cyl"][0])), "{:.1f}")
rng = lambda rs, f: (min(f(r) for r in rs), max(f(r) for r in rs))
lo, hi = rng(S0, lambda r: r["R_at_V302"][0]); put("RValNoRtgLo", lo, "{:.2f}"); put("RValNoRtgHi", hi, "{:.2f}")
lo, hi = rng(RTG, lambda r: r["R_at_V302"][0]); put("RValRtgLo", lo, "{:.2f}"); put("RValRtgHi", hi, "{:.2f}")
assert max(r["R_at_V302"][0] for r in RTG) < min(r["R_at_V302"][0] for r in S0), "V302 ranges overlap: rewrite Sec. III F"
assert max(r["k_cav"][0] for r in S0) < 0.05 < min(r["k_cav"][0] for r in RTG), "cavity K+ statement: rewrite Sec. III F"
W = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve"]
GW = json.load(open(H + "/out2/gate_water.json")); assert list(GW) == list(R), "gate_water.json is stale: run gate_water.py"
occ = {NAME[l]: 100 * GW[l]["frac_occupied"] for l in R}; wet = [k for k, v in occ.items() if v > 0]; dry = [k for k, v in occ.items() if v == 0]
mac["NInWord"] = W[len(wet)]; put("PInLo", min(occ[k] for k in wet), "{:.1f}"); put("PInHi", max(occ.values()), "{:.0f}")
mac["InDryList"] = " and ".join(dry) if dry else "none"
crossers = [l for l in R if GW[l]["n_crossing_molecules"] > 0]
assert len(crossers) == 1, ("water crossings: the text says 'in one trajectory'", [NAME[l] for l in crossers])
X = GW[crossers[0]]; mac["CrossTraj"] = NAME[crossers[0]]; mac["NCrossWord"] = W[X["n_crossing_molecules"]]
assert all(v["origin"] == "Y" and v["exit"] == "C" for v in X["crossings"]), "direction of the crossings: rewrite Sec. III E"
put("CrossTa", np.floor(min(v["t_in"] for v in X["crossings"])), "{:.0f}"); put("CrossTb", np.ceil(max(v["t_out"] for v in X["crossings"])), "{:.0f}")
put("CrossNMol", X["n_molecules"], "{:d}"); put("CrossNVis", X["n_visits"], "{:d}"); put("CrossNCyt", X["from_cytoplasm"], "{:d}"); mac["CrossMaxWord"] = W[X["max_molecules"]]
assert X["from_cytoplasm"] > X["n_visits"] / 2, "'most of them from the cytoplasmic side': rewrite Sec. III E"
assert all(GW[l]["from_cytoplasm"] == 0 and GW[l]["to_cytoplasm"] == 0 and GW[l]["max_molecules"] <= 1 for l in R if l not in crossers), \
    "'one molecule at a time, from the cavity and back' in the other trajectories: rewrite Sec. III E"
assert max(GW[l]["frac_wire"] for l in R) == 0.0, "a continuous water chain spans the gate in some frame: rewrite abstract, III E, conclusion"
kin = 0
for l in R:
    d_ = np.load(f"{H}/out2/{l}.npz", allow_pickle=True); zc_ = 0.5 * (d_["zb"][:-1] + d_["zb"][1:]); m_ = d_["t_ns"] >= 20
    kin += int((d_["k4"][m_][:, (zc_ > -8) & (zc_ < 2)].sum(1) > 0).sum())
assert kin == 0, "a K+ ion enters the gate: rewrite abstract, III E, discussion"
C_ = [GW[l]["contacts"] for l in R if GW[l]["contacts"]]
put("HbOO", np.median([c["d_og_median"] for c in C_]) / 10, "{:.3f}"); put("HbNLo", min(c["n_og_mean"] for c in C_), "{:.1f}"); put("HbNHi", max(c["n_og_mean"] for c in C_), "{:.1f}")
put("HbRLo", 100 * min(c["frac_R_below_water"] for c in C_), "{:.0f}"); put("HbRHi", 100 * max(c["frac_R_below_water"] for c in C_), "{:.0f}")
assert min(c["frac_hbond"] for c in C_) > 0.9, "water inside the gate not hydrogen bonded to Ser314: rewrite Sec. III E"
ngup = []
for l in R:
    d_ = np.load(f"{H}/out2/{l}.npz", allow_pickle=True); zc_ = 0.5 * (d_["zb"][:-1] + d_["zb"][1:]); w6_ = d_["w6"][d_["t_ns"] >= 20]
    ngup.append(100 * w6_[:, (zc_ > 2) & (zc_ < 5)].sum(1).mean() / w6_[:, (zc_ > -5) & (zc_ < 5)].sum(1).mean())
put("PNgUpLo", min(ngup), "{:.0f}"); put("PNgUpHi", max(ngup), "{:.0f}")
assert all(GW[l]["from_cavity"] + GW[l]["to_cavity"] > 0 for l in R if GW[l]["n_visits"] > 0), "'passed the Ser314 ring in every trajectory with water inside': rewrite Discussion"
occS0 = [occ[NAME[l]] for l in R if NAME[l].startswith("S0")]; assert max(occS0) - min(occS0) > 10, "'varies between trajectories of the same composition': rewrite Sec. III F"
pk = []
for l in R:   # widest point of the mean on-axis profile between the two rings (-0.5 < z < -0.1 nm)
    d_ = np.load(f"{H}/out2/{l}.npz", allow_pickle=True); zs_ = d_["zs"]; prof = d_["rz"][d_["t_ns"] >= 20][:, 0, 1, :].mean(0) / 10
    pk.append(prof[(zs_ > -5) & (zs_ < -1)].max())
put("RPocketLo", min(pk), "{:.2f}"); put("RPocketHi", max(pk), "{:.2f}"); assert min(pk) > 0.14, "'the space between the rings is wider than a water molecule': rewrite Sec. III E"
n = len(R); mac["NTrajWord"] = W[n]; mac["NTrajWordCap"] = W[n].capitalize(); put("TProdMu", tprod / 1000, "{:.2f}")
reps = [l for l in R if SEED[l] is not None]; mac["NRepWordCap"] = W[len(reps)].capitalize()
bysys = {}
for l in reps: bysys.setdefault(NAME[l][:2], []).append(NAME[l])
mac["RepList"] = " and ".join(f"{', '.join(v)} from {k}-a" for k, v in bysys.items())
put("SeedWindow", int(5 * np.ceil((100 - min(SEED[l] for l in reps)) / 5)), "{:d}")
mac["NRtgTrajWord"] = W[len(RTG)]
row = []
for s_ in ("S0", "S2", "S3"):
    ls = [l for l in R if NAME[l].startswith(s_)]; b_ = [NAME[l][-1] for l in ls if LENGTH[l] == 200]
    row.append("a (100)" + (", " + ", ".join(b_) + " (200)" if b_ else ""))
mac["TrajRow"] = "Trajectories (length, ns) & " + " & ".join(row) + r" \\"
ksf = {NAME[l]: r["k_sf"][0] for l, r in R.items()}
low = [k for k, v in ksf.items() if v < 1.5]; ok = [k for k, v in ksf.items() if v >= 1.5]
assert all(v > 1.9 for k, v in ksf.items() if k in ok) and all(0.8 < ksf[k] < 1.2 for k in low), ("filter statement: rewrite", ksf)
assert low and all(k.startswith("S0-") and k != "S0-a" for k in low), ("filter statement: rewrite", ksf)
lowtxt = ("trajectory " if len(low) == 1 else "trajectories ") + (low[0] if len(low) == 1 else ", ".join(low[:-1]) + " and " + low[-1])
LAB = {NAME[l]: l for l in R}
def ksf_series(l):
    d_ = np.load(f"{H}/out2/{l}.npz", allow_pickle=True); zc_ = 0.5 * (d_["zb"][:-1] + d_["zb"][1:])
    return d_["t_ns"], d_["k4"][:, (zc_ > 20) & (zc_ < 35)].sum(1).astype(float)
t_a, k_a = ksf_series(LAB["S0-a"]); lost_a = None
loss = {}
for k in low:
    t_, k_ = ksf_series(LAB[k]); rm = np.convolve(k_, np.ones(10) / 10, mode="same"); dt = t_[1] - t_[0]; w = int(round(20 / dt))
    if k_[t_ < 1].mean() < 1.5:
        loss[k] = None; assert SEED[LAB[k]] > t_a[np.where(np.convolve(k_a, np.ones(10) / 10, mode="same") >= 1.5)[0].max()], ("filter statement: rewrite", k)
    else:
        i = next(i for i in range(len(rm) - w) if (rm[i:i + w] < 1.5).all()); loss[k] = 5 * round(t_[i] / 5); assert loss[k] < 60, ("filter statement: rewrite", k, loss[k])
start1 = [k for k in low if loss[k] is None]; lost = [k for k in low if loss[k] is not None]
mac["FilterSentence"] = (f"The selectivity filter holds two to three \\Kp{{}} ions in {W[len(ok)]} trajectories and a single ion in {lowtxt}"
                         + "".join(f", in {k} after the first {loss[k]}~ns" for k in lost))
fd = []
if start1: fd.append(f"{' and '.join(start1)} " + ("was" if len(start1) == 1 else "were") + " started from the last frame of S0-a, in which the filter had just lost an ion, and " + ("holds" if len(start1) == 1 else "hold") + " one ion throughout")
for k in lost: fd.append(f"the filter of {k} lost one of its two ions after about {loss[k]}~ns")
mac["FilterDiffSentence"] = ("Third, the filter holds one \\Kp{} ion in " + lowtxt + ", against two to three in the other trajectories: " + "; ".join(fd) + ".")
nS0, nS2 = len(S0), len(S2); assert nS2 == 1
mac["FewTrajPhrase"] = "S0 and S2 are represented by two trajectories and one trajectory" if nS0 == 2 else "S2 is represented by a single trajectory"
mac["FewTrajDisc"] = "Two of the three compositions are represented by one or two trajectories." if nS0 <= 2 else "One of the three compositions is represented by a single trajectory."
CM = json.load(open(H + "/out2/composition.json")); HC = json.load(open(H + "/out2/hole_check.json"))["summary"]; RM = json.load(open(H + "/out2/replica_memory.json")); HB = json.load(open(H + "/out2/gate_hbonds.json"))
assert list(HB) == list(R), "gate_hbonds.json is stale: run gate_hbonds.py"
assert all(abs(CM[s_]["total"]) < 1e-3 for s_ in CM), "a system is not neutral"
assert CM["S2"]["filter_sites"] == CM["S3"]["filter_sites"] == ["S1", "S3"], "filter sites: rewrite Methods"
